function costPurchase(int $x,string $qty='10',string $amount='30',?string $delivered=null):int{global $a,$r,$owner,$staff,$clock;$p=new PurchaseService($a,$delivered??$clock);$category=(int)$r->run('SELECT id FROM expense_categories WHERE active=1 ORDER BY id LIMIT 1')->fetchColumn();$id=$p->execute($staff,'request',['type'=>'stock','title'=>'Synthetic costing receipt','supplier'=>'Synthetic costing supplier '.sk(),'phone'=>'0000000000','purpose'=>'Synthetic purchase for weighted pool','estimate'=>$amount,'method'=>'momo','category_id'=>(string)$category,'extra_id'=>(string)$x,'qty'=>$qty],sk())['id'];$v=fn()=>['id'=>(string)$id,'version'=>$p->detail($owner,$id)['version']];$p->execute($owner,'approve',$v()+['decision'=>'approve','limit'=>$amount,'reason'=>'Synthetic prior authority'],sk());$p->execute($staff,'commit',$v()+['amount'=>$amount,'committed_at'=>$delivered??$clock,'confirmed'=>'1'],sk());$p->execute($staff,'receive',$v()+['actual_cost'=>$amount,'delivered_at'=>$delivered??$clock,'description'=>'Complete delivery','missing_evidence'=>'Synthetic independently checked receipt','payment_status'=>'unpaid','received'=>'1'],sk());$p=new PurchaseService($a,$clock);$p->execute($owner,'post',$v()+['verified'=>'1','stock_verified'=>'1','reason'=>'Verified complete delivery and cost'],sk());return $id;}
function costCorrect(int $id,array $more=[]):void{global $a,$owner,$staff,$clock;$s=new PurchaseCorrectionService($a,$clock);$v=$s->source($staff,'purchase',$id);$case=$s->execute($staff,'request',$more+['source_type'=>'purchase','source_id'=>(string)$id,'source_token'=>$v['token'],'type'=>'cost','amount'=>'28','reason'=>'Original linked source verified','confirmed'=>'1'],sk())['id'];$s->execute($owner,'post',['id'=>(string)$case,'version'=>$s->detail($owner,$case)['version'],'reason'=>'Owner verified linked correction','verified'=>'1','stock_verified'=>'1'],sk());}
$x=openingCost('20','40');$purchase=costPurchase($x);sa(cv($x)['qty']===3000&&cv($x)['value']===7000,'accepted purchase cost and stock enter one weighted pool');$orig=$r->run("SELECT * FROM expenses WHERE reference_no=?",['PURCHASE-'.$purchase])->fetch();
$stay=new \Tivoli\Service\StayService($a,$clock);$stay->execute($staff,'extra',['booking_id'=>(string)$booking,'extra_id'=>(string)$x,'qty'=>'6','settlement'=>'room'],sk());$id=siReport($x);siApprove($id);$comp=siReport($x,'complimentary','1');siApprove($comp);siDispose($comp);siDispose($id);$v=cv($x);sa($v['costs']===['sales'=>1400,'loss'=>467,'complimentary'=>233,'returns'=>0]&&$v['value']===4900&&$v['error']===null,'approved prototype exact consumption and inventory values reproduced');
$source=$r->run("SELECT payload FROM finance_events WHERE kind='ic_source' AND target_type='inventory_cost' AND target_id=? ORDER BY id",[(string)$x])->fetchAll();sa(array_sum(array_map(fn($e)=>json_decode($e['payload'],true)['acquisition_delta'],$source))===3000,'eligible purchase cost is added back exactly once');
costCorrect($purchase);$v=cv($x);sa(array_sum($v['costs'])===2040&&$v['value']===4760&&$v['error']===null,'purchase cost correction allocates exact consumed and remaining value deltas');sa($r->run('SELECT * FROM expenses WHERE id=?',[$orig['id']])->fetch()===$orig,'purchase correction and costing retain original expense byte for byte');
$source=$r->run("SELECT payload FROM finance_events WHERE kind='ic_source' AND target_type='inventory_cost' AND target_id=? ORDER BY id",[(string)$x])->fetchAll();sa(array_sum(array_map(fn($e)=>json_decode($e['payload'],true)['acquisition_delta'],$source))===2800,'linked purchase adjustment changes addback without double expensing');
$x=openingCost('0','0');$purchase=costPurchase($x,'10','50');costCorrect($purchase,['type'=>'stock','stock_basis'=>'actual_return','qty'=>'2','amount'=>'42','actual_at'=>$clock,'return_reference'=>'SYNTHETIC-RETURN-'.sk()]);$v=cv($x);sa($v['qty']===800&&$v['value']===4000&&$v['costs']['returns']===200&&$v['error']===null,'supplier short credit recognizes only actual return carrying difference');
$x=openingCost('0','0');$purchase=costPurchase($x,'10','50');costCorrect($purchase,['type'=>'stock','stock_basis'=>'quantity_error','qty'=>'8','amount'=>'40']);$v=cv($x);sa($v['qty']===800&&$v['value']===4000&&array_sum($v['costs'])===0&&$v['error']===null,'receipt quantity correction rebases original receipt without invented consumption');
$x=sx('0');$purchase=costPurchase($x,'10','50');$count=start($staff,[$x]);countLine($staff,$count,$x,'10');send($staff,$count);approve($count);$cost->execute($owner,'start',['extra_id'=>(string)$x,'count_id'=>(string)$count,'total'=>'','evidence'=>'Opening receipt still under review','verified'=>'1'],sk());costCorrect($purchase,['amount'=>'40']);$v=$cost->item($owner,$x);$cost->execute($owner,'evidence',['extra_id'=>(string)$x,'version'=>$v['version'],'total'=>'40','purchase_id'=>(string)$purchase,'evidence'=>'Accepted original purchase and corrected source reviewed','verified'=>'1'],sk());sa(cv($x)['value']===4000&&cv($x)['error']===null,'late linked opening evidence does not apply existing purchase corrections twice');$bridgeRows=$r->run("SELECT payload FROM finance_events WHERE kind='ic_source' AND target_type='inventory_cost' AND target_id=?",[(string)$x])->fetchAll();sa(array_sum(array_map(fn($e)=>(int)json_decode($e['payload'],true)['acquisition_delta'],$bridgeRows))===-1000,'late opening link classifies previously unmatched cost correction once in current period');
$x=openingCost('10','50');$purchase=costPurchase($x,'10','30');$v=$cost->item($owner,$x);sd(fn()=>$cost->execute($owner,'evidence',['extra_id'=>(string)$x,'version'=>$v['version'],'total'=>'30','purchase_id'=>(string)$purchase,'evidence'=>'Wrong newer receipt cannot support earlier stock','verified'=>'1'],sk()),'post-cutover purchase cannot be reused as opening stock evidence');
